"""Smoke-test the offline observer UI against a generated Android test export."""
import argparse
import html
import json
from pathlib import Path
import re
import subprocess
import tempfile

from evaluation.field_handoff import score


def verify(browser, device):
    # All events are generated by FieldExportTest. Nothing from a real session belongs here.
    script = """
    (async()=>{
      const phoneFile=FIXTURE;
      let now=0;
      Object.defineProperty(performance,'now',{value:()=>now});
      el('start').click();el('round').value=phoneFile.round;
      const at=phoneFile.phone[0].at_s*1000;
      now=at-300;el('sounds').children[0].click();
      now=at+100;el('sounds').children[0].click();
      now=at+250;el('watch').click();
      now=phoneFile.duration_s*1000+500;el('stop').click();
      const transfer=new DataTransfer();
      transfer.items.add(new File([JSON.stringify(phoneFile)],'device.json',{type:'application/json'}));
      el('file').files=transfer.files;await el('file').onchange();
      selections.get(1).value='0';el('complete').checked=true;
      HTMLAnchorElement.prototype.click=async function(){
        const observation=await (await fetch(this.href)).text();
        const pre=document.createElement('pre');pre.id='result-json';pre.textContent=observation;document.body.append(pre);
      };
      el('save').click();
    })();
    """
    with tempfile.TemporaryDirectory() as temp:
        page=Path(temp)/'observer.html'
        source=Path(__file__).with_name('field-observer.html').read_text(encoding='utf-8')
        script=script.replace('FIXTURE',json.dumps(device).replace('<',r'\u003c'))
        page.write_text(source.replace('</html>', '<script>'+script+'</script></html>'),encoding='utf-8')
        result=subprocess.run([browser,'--headless','--disable-gpu','--disable-background-networking',
                               '--user-data-dir='+str(Path(temp)/'profile'),'--dump-dom',
                               '--virtual-time-budget=5000',page.as_uri()],capture_output=True,timeout=60,check=True)
        output=result.stdout.decode('utf-8')
        match=re.search(r'<pre id="result-json">(.*?)</pre>',output,re.S)
        if not match:
            raise RuntimeError('Browser did not produce a completed observation')
        report=score(device,json.loads(html.unescape(match[1])),source='synthetic')
        assert report['verified_end_to_end_hits']==1 and report['phone']['false_alerts']==1
        assert report['blocked']==1 and report['simulated_excluded']==1
        assert abs(report['end_to_end_latency_p50_s']-.55)<.002
        print('Android export -> browser observation -> D scoring: PASS (synthetic)')


if __name__ == '__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('browser')
    parser.add_argument('fixture',type=Path)
    args=parser.parse_args()
    verify(args.browser,json.loads(args.fixture.read_text(encoding='utf-8')))
